<?php
declare(strict_types=1);
/** One reviewed repair of the imported workforce, preserving account and relational IDs. */
function v28_document():array { $p=EP_ROOT.'/private/prepared-data-v28.json';if(!is_file($p))fail('ملف تصحيح V28 غير موجود؛ ارفع حزمة الاستضافة.');return decode(file_get_contents($p)); }
function v28_plan(array $doc):array {
 $users=query('SELECT * FROM ep_users')->fetchAll();$rows=[];$errors=[];$seen=[];$codes=[];
 foreach($doc['people']as $r){$serial=(int)$r['A'];$code='EMP-'.str_pad((string)$serial,4,'0',STR_PAD_LEFT);$previous=current(array_filter($doc['previous_people'],fn($p)=>$p['B']===$r['B']));$found=[];
  foreach($users as $u){if($u['role']==='admin')continue;$p=decode($u['profile_json']);$sameCivil=!empty($r['D'])&&!empty($p['civil_id'])&&(string)$p['civil_id']===(string)$r['D'];$oldSerial=$previous&&isset($p['setup_serial'])&&(int)$p['setup_serial']===(int)$previous['A'];if($sameCivil||$u['name']===$r['B'])$found[(int)$u['id']]=$u;}
  if(count($found)>1)$errors[]='تعارض هوية: '.$r['B'];$target=$found?array_values($found)[0]:null;if($target&&$target['name']!==$r['B'])$errors[]='الاسم لا يطابق الهوية: '.$r['B'];if($target&&isset($seen[$target['id']]))$errors[]='موظف مرتبط بأكثر من اسم';if($target)$seen[$target['id']]=true;
  if($serial<1||isset($codes[$code]))$errors[]='مسلسل مكرر أو غير صالح';$codes[$code]=true;$rows[]=['serial'=>$serial,'name'=>$r['B'],'id'=>$target?(int)$target['id']:null,'old_code'=>$target?employee_key($target):'','new_code'=>$code];
 }
 foreach($users as $u)if($u['role']!=='admin'&&!isset($seen[$u['id']])&&isset($codes[employee_key($u)]))$errors[]='كود مستخدم لموظف خارج دفعة التصحيح: '.employee_key($u);
 foreach($users as $a)if($a['role']==='admin'){$adminProfile=decode($a['profile_json']);$adminCode=(string)($adminProfile['employee_code']??$a['username']);if(isset($codes[$adminCode]))$errors[]='كود المشرف يتعارض مع كود موظف؛ راجع الهوية قبل التصحيح';if(query("SELECT id FROM ep_history WHERE employee_code=? AND kind<>'salary_history'",[$adminCode])->fetch())$errors[]='توجد بيانات موظف تاريخية للمشرف تحتاج مراجعة';foreach(['ep_events','ep_payroll','ep_bank_payroll','ep_locations']as $table)if(query('SELECT id FROM '.$table.' WHERE user_id=?',[$a['id']])->fetch())$errors[]='توجد سجلات تشغيل للمشرف تحتاج مراجعة قبل فصل حسابه';if(query("SELECT id FROM ep_records WHERE user_id=? AND module NOT IN ('service_period','service_terms','company_file','corporate_document','attachment_archive')",[$a['id']])->fetch())$errors[]='توجد سجلات موظف للمشرف تحتاج مراجعة';}
 foreach($rows as $r)if($r['id']){foreach(query('SELECT * FROM ep_history WHERE employee_code=?',[ $r['old_code'] ])->fetchAll()as $h)if(in_array($h['kind'],['payroll','bank'],true))$errors[]='يوجد كشف تاريخي يحتاج مراجعة قبل التصحيح: '.$r['name'];}
 $periods=[];foreach($doc['periods']as $p){$serial=(int)$p['A'];$person=current(array_filter($doc['people'],fn($r)=>(int)$r['A']===$serial));if(!$person||$p['B']!==$person['B']){$errors[]='اسم فترة لا يطابق المسلسل';continue;}$from=valid_date($p['C']);$to=valid_date($p['D']?:null);if(!$from||($to&&$to<$from))$errors[]='تاريخ فترة غير صالح';foreach($periods[$serial]??[]as $v)if($from<=($v[1]??'9999-12-31')&&($to??'9999-12-31')>=$v[0])$errors[]='فترات متداخلة';$periods[$serial][]=[$from,$to];if(!in_array($p['E'],array_column($doc['companies'],'B'),true)||($p['F']&&!in_array($p['F'],array_column($doc['companies'],'B'),true)))$errors[]='شركة غير معروفة';}
 $salaryKeys=[];foreach($doc['salaries']as $s){$person=current(array_filter($doc['people'],fn($r)=>(int)$r['A']===(int)$s['serial']));$date=valid_date($s['date']);$key=$s['serial'].'|'.$s['date'];if(!$person||$person['B']!==$s['name']||!$date||isset($salaryKeys[$key])||!is_numeric($s['salary'])||$s['salary']<0||(!$s['fixed_salary']&&$s['salary']!=0))$errors[]='سجل راتب غير صالح';$salaryKeys[$key]=true;$inside=false;foreach($periods[(int)$s['serial']]??[]as [$from,$to])if($date>=$from&&$date<=($to??'9999-12-31'))$inside=true;if(!$inside)$errors[]='راتب خارج فترة الخدمة: '.$s['name'];}
 foreach($doc['people']as $person){$serial=(int)$person['A'];if(empty($periods[$serial]))$errors[]='فترة خدمة مفقودة: '.$person['B'];foreach($periods[$serial]??[]as [$from,$to])if(!array_filter($doc['salaries'],fn($s)=>(int)$s['serial']===$serial&&$s['date']===$from))$errors[]='راتب بداية فترة الخدمة مفقود: '.$person['B'];}
 foreach($rows as $r)if($r['id']){foreach(['ep_payroll','ep_bank_payroll']as $table)if(query('SELECT id FROM '.$table." WHERE user_id=? AND status IN ('approved','submitted')",[$r['id']])->fetch())$errors[]='يوجد كشف معتمد؛ راجعه قبل تصحيح بيانات '.$r['name'];}
 return ['rows'=>$rows,'errors'=>array_values(array_unique($errors)),'counts'=>['companies'=>count($doc['companies']),'employees'=>count($rows),'periods'=>count($doc['periods']),'salaries'=>count($doc['salaries'])]];
}
function v28_codes(array $v,array $map):array {foreach($v as $k=>$x){if(is_array($x))$v[$k]=v28_codes($x,$map);elseif(in_array($k,['code','employee_code'],true)&&is_string($x)&&isset($map[$x]))$v[$k]=$map[$x];}return $v;}
function v28_base_action(string $action,array $u,array $b):array {
 admin_only($u);$doc=v28_document();$hash=hash('sha256',jencode($doc));$done=query("SELECT value_json FROM ep_settings WHERE setting_key='data_correction_v28'")->fetchColumn();if($done){$v=decode($done);return ['already_applied'=>true,'rows'=>$v['mapping'],'errors'=>[],'hash'=>$hash,'counts'=>$v['counts']];}
 $plan=v28_plan($doc);if($action==='v28_base_preview'){$_SESSION['v28_base_preview']=$hash;return $plan+['hash'=>$hash];}
 if($action!=='v28_base_commit')fail('عملية غير موجودة.',404);if(!hash_equals($_SESSION['v28_base_preview']??'',(string)($b['hash']??''))||!hash_equals($hash,(string)($b['hash']??'')))fail('أعد معاينة التصحيح.');if($plan['errors'])fail(implode('\n',$plan['errors']));
 require_once __DIR__.'/backups.php';$backup=backup_run($u,'before_data_correction_v28');db()->beginTransaction();query('SELECT id FROM ep_users WITH (UPDLOCK, HOLDLOCK)');$plan=v28_plan($doc);if($plan['errors'])fail(implode('\n',$plan['errors']));
 $companies=[];foreach($doc['companies']as $r){$c=query('SELECT * FROM ep_companies WHERE name=?',[$r['B']])->fetch();if(!$c){$code=next_code('company');query('INSERT INTO ep_companies(code,name,legal_name,bank_name,bank_account,labor_file,active,created_at) VALUES(?,?,?,?,?,?,?,?)',[$code,$r['B'],$r['C'],str_replace('COMMERCAIL','COMMERCIAL',$r['D']),trim($r['E']),$r['F'],$r['G']==='مفعلة'?1:0,utc_now()]);$c=company_by_code($code);}else query('UPDATE ep_companies SET legal_name=?,bank_name=?,bank_account=?,labor_file=?,active=? WHERE id=?',[$r['C'],str_replace('COMMERCAIL','COMMERCIAL',$r['D']),trim($r['E']),$r['F'],$r['G']==='مفعلة'?1:0,$c['id']]);$companies[$r['B']]=$c['code'];}
 $map=[];$staff=[];foreach($plan['rows']as $item){$r=current(array_filter($doc['people'],fn($p)=>(int)$p['A']===$item['serial']));$id=$item['id'];if($id){$u0=query('SELECT * FROM ep_users WHERE id=?',[$id])->fetch();$p=array_replace(decode($u0['profile_json']),setup_profile($r));$map[$item['old_code']]=$item['new_code'];}else{$p=setup_profile($r);$login='staff-'.bin2hex(random_bytes(8));query("INSERT INTO ep_users(username,password_hash,name,role,active,profile_json,created_at) VALUES(?,?,?,'employee',0,?,?)",[$login,password_hash(bin2hex(random_bytes(32)),PASSWORD_DEFAULT),$r['B'],jencode($p),utc_now()]);$id=(int)db()->lastInsertId();}$p['employee_code']=$item['new_code'];$p['setup_serial']=$item['serial'];query('UPDATE ep_users SET profile_json=? WHERE id=?',[jencode($p),$id]);$staff[$item['serial']]=query('SELECT * FROM ep_users WHERE id=?',[$id])->fetch();}
 // Rewrite references once from original values, so code shifts never cascade.
 $histories=query('SELECT id,employee_code,body_json FROM ep_history')->fetchAll();$temporary='V28-'.bin2hex(random_bytes(6)).'-';foreach($histories as $h)if(isset($map[$h['employee_code']]))query('UPDATE ep_history SET employee_code=? WHERE id=?',[$temporary.$h['id'],$h['id']]);foreach($histories as $h)if(isset($map[$h['employee_code']]))query('UPDATE ep_history SET employee_code=?,body_json=? WHERE id=?',[$map[$h['employee_code']],jencode(v28_codes(decode($h['body_json']),$map)),$h['id']]);
 foreach($staff as $serial=>$s){$id=(int)$s['id'];query("DELETE FROM ep_records WHERE user_id=? AND module='service_period'",[$id]);query("DELETE FROM ep_history WHERE employee_code=? AND kind='salary_history'",[employee_key($s)]);query("DELETE FROM ep_payroll WHERE user_id=? AND status='draft'",[$id]);query("DELETE FROM ep_bank_payroll WHERE user_id=? AND status='draft'",[$id]);$pp=array_values(array_filter($doc['periods'],fn($p)=>(int)$p['A']===$serial));usort($pp,fn($a,$b)=>strcmp($a['C'],$b['C']));$profile=decode($s['profile_json']);$latest=null;
  foreach($pp as $r){$note=$r['K']??'';$v=['company_code'=>$companies[$r['E']],'residence_company_code'=>$r['F']?$companies[$r['F']]:'','department'=>$r['G'],'job_title'=>$r['H'],'staff_type'=>['شريك'=>'partner','مكتب'=>'office','مندوب'=>'rep','عن بُعد'=>'remote'][$r['I']],'attendance'=>!str_contains($note,'لا يخضع'),'leave'=>$r['J']==='نعم','payroll'=>!str_contains($note,'تحويل بنك فقط'),'bank'=>true,'note'=>$note];query("INSERT INTO ep_records(module,user_id,title,date_from,date_to,status,body_json,created_at,updated_at) VALUES('service_period',?,?,?,?,'approved',?,?,?)",[$id,'فترة خدمة مصححة V28',$r['C'],$r['D']?:null,jencode($v),utc_now(),utc_now()]);$latest=$v;}
  if(!$latest)fail('فترة الخدمة مفقودة');$profile=array_replace($profile,['company_code'=>$latest['company_code'],'residence_company_code'=>$latest['residence_company_code'],'attendance_required'=>$latest['attendance'],'leave_eligible'=>$latest['leave'],'payroll_visible'=>$latest['payroll'],'bank_visible'=>true]);$ss=array_values(array_filter($doc['salaries'],fn($r)=>(int)$r['serial']===$serial));usort($ss,fn($a,$b)=>strcmp($a['date'],$b['date']));$current=['salary'=>0,'fixed_salary'=>false];foreach($ss as $r){$body=['code'=>employee_key($s),'effective_from'=>$r['date'],'salary'=>(float)$r['salary'],'fixed_salary'=>$r['fixed_salary'],'note'=>$r['note']];query('INSERT INTO ep_history(kind,employee_code,period_key,body_json,imported_at,imported_by) VALUES(?,?,?,?,?,?)',['salary_history',employee_key($s),$r['date'],jencode($body),utc_now(),$u['id']]);if($r['date']<=local_time()->format('Y-m-d'))$current=$r;}$profile['fixed_salary']=$current['fixed_salary'];if($serial===8)$profile['additional_job']='مندوب الشؤون والجوازات';query('UPDATE ep_users SET hired_on=?,salary=?,department=?,job_title=?,staff_type=?,profile_json=? WHERE id=?',[$pp[0]['C'],(float)$current['salary'],$latest['department'],$latest['job_title'],$latest['staff_type'],jencode($profile),$id]);}
 // Remove employment artefacts belonging to administrative-only accounts; retain audit/actions.
 foreach(query("SELECT * FROM ep_users WHERE role='admin'")->fetchAll()as $a){$p=decode($a['profile_json']);$old=(string)($p['employee_code']??$a['username']);query("DELETE FROM ep_records WHERE user_id=? AND module IN ('service_period','service_terms')",[$a['id']]);query("DELETE FROM ep_history WHERE employee_code=? AND kind='salary_history'",[$old]);foreach(['employee_code','setup_serial','fixed_salary','company_code','residence_company_code','attendance_required','leave_eligible','payroll_visible','bank_visible','bank_salary']as $k)unset($p[$k]);query('UPDATE ep_users SET hired_on=NULL,salary=0,staff_type=?,department=?,job_title=?,show_sick=0,profile_json=? WHERE id=?',['system','','المشرف العام',jencode($p),$a['id']]);}
 $mapping=[];foreach($staff as $serial=>$s)$mapping[]=['serial'=>$serial,'name'=>$s['name'],'code'=>employee_key($s),'id'=>(int)$s['id'],'new_code'=>employee_key($s)];$seq=max(count($staff),(int)(json_decode(query("SELECT value_json FROM ep_settings WHERE setting_key='sequence_employee'")->fetchColumn()?:'0',true)));query("MERGE INTO ep_settings WITH (HOLDLOCK) AS target USING (VALUES (?, ?)) AS source (setting_key, value_json) ON target.setting_key=source.setting_key WHEN MATCHED THEN UPDATE SET value_json=source.value_json WHEN NOT MATCHED THEN INSERT (setting_key, value_json) VALUES (source.setting_key, source.value_json);",['sequence_employee',jencode($seq)]);
 query('INSERT INTO ep_settings(setting_key,value_json) VALUES(?,?)',['data_correction_v28',jencode(['hash'=>$hash,'mapping'=>$mapping,'counts'=>$plan['counts'],'backup'=>$backup['id']])]);audit('data_correction','V28',['counts'=>$plan['counts'],'backup'=>$backup['id']]);db()->commit();unset($GLOBALS['EP_SERVICE_CACHE'],$GLOBALS['EP_SALARY_CACHE']);return ['mapping'=>$mapping,'backup_id'=>$backup['id']];
}

function v28_secondary_prepare():array {
 $doc=decode(file_get_contents(EP_ROOT.'/private/prepared-data-v28.json'));$errors=[];$map=[];
 foreach($doc['people']as $p){$s=employee_by_code('EMP-'.str_pad((string)$p['A'],4,'0',STR_PAD_LEFT));if(!$s||$s['name']!==$p['B'])$errors[]='هوية الموظف تحتاج تصحيح V28: '.$p['B'];else $map[(int)$p['A']]=$s;}
 $preview=['counts'=>['employees'=>count($doc['people']),'leave_history'=>count($doc['leave_history']),'leave_settlements'=>count($doc['leave_settlements']),'banks'=>count(array_filter($doc['banks'],fn($b)=>$b['method']==='bank'))],'errors'=>$errors,'warnings'=>['محمود صابر EMP-0054 موقوف الصرف؛ المستحقات لا تلغى','الصفوف بدون حركات لا تثبت اكتمال التاريخ أو صفر رصيد','المبلغ التاريخي محفوظ كما صرف؛ لا يعاد حسابه بالراتب الحالي'],'sources'=>$doc['sources'],'hash'=>hash('sha256',jencode($doc))];
 return [$doc,$map,$preview];
}
function v28_secondary_import(array $u,array $b):array {
 admin_only($u);[$doc,$map,$p]=v28_secondary_prepare();if($p['errors'])fail(implode('\n',$p['errors']));if(!hash_equals($_SESSION['v28_secondary_preview']??'',(string)($b['hash']??''))||!hash_equals($p['hash'],(string)($b['hash']??'')))fail('أعد معاينة بيانات V26.');
 $done=query("SELECT value_json FROM ep_settings WHERE setting_key='prepared_v28_history'")->fetchColumn();if($done){if(decode($done)['hash']!==$p['hash'])fail('دفعة مختلفة مسجلة؛ استخدم استيراد تعديل مدقق.');return ['already_applied'=>true];}
 $backup=backup_run($u,'before_v26_data');db()->beginTransaction();query('SELECT id FROM ep_users WITH (UPDLOCK, HOLDLOCK)');$existingBatch=query("SELECT value_json FROM ep_settings WHERE setting_key='prepared_v28_history'")->fetchColumn();if($existingBatch){db()->rollBack();return ['already_applied'=>true];}foreach($map as $staff)financial_invalidate((int)$staff['id'],service_state($staff,local_time()->format('Y-m-d'))['from']??'1900-01-01');
 foreach($doc['leave_history']as $l){$s=$map[$l['serial']];$key=$l['from'].'_'.$l['to'];$body=['from'=>$l['from'],'to'=>$l['to'],'return_date'=>(new DateTimeImmutable($l['to']))->modify('+1 day')->format('Y-m-d'),'leave_type'=>'إجازة','note'=>$l['note'],'source'=>'V26'];$existing=query("SELECT body_json FROM ep_history WHERE kind='leave_history' AND employee_code=? AND period_key=?",[employee_key($s),$key])->fetch();if($existing){$old=decode($existing['body_json']);if($old['from']!==$l['from']||$old['to']!==$l['to'])fail('تعارض إجازة تاريخية');continue;}query('INSERT INTO ep_history(kind,employee_code,period_key,body_json,imported_at,imported_by) VALUES(?,?,?,?,?,?)',['leave_history',employee_key($s),$key,jencode($body),utc_now(),$u['id']]);if(!empty($l['late_open'])){$history=(int)db()->lastInsertId();$rid=v26_insert('leave',(int)$s['id'],$l['from'],$l['to'],['late_open'=>true,'history_id'=>$history,'expected_return'=>$body['return_date'],'reason'=>$l['note'],'source'=>'historical_open_leave']);audit('historical_open_leave','record:'.$rid,['history_id'=>$history]);}}
 foreach($doc['leave_settlements']as $l){$s=$map[$l['serial']];
 if(!empty($l['original_source_date'])&&$l['original_source_date']!==$l['date']){
  $prior=query("SELECT * FROM ep_history WHERE kind='leave_settlement' AND employee_code=? AND period_key=?",[employee_key($s),$l['original_source_date']])->fetch();
  if($prior){$body=decode($prior['body_json']);if(abs((float)$body['days']-$l['days'])>1e-8||abs((float)$body['amount']-$l['amount'])>0.0005)fail('الصرف بالتاريخ الأصلي لا يطابق التصحيح المعتمد');if(query("SELECT id FROM ep_history WHERE kind='leave_settlement' AND employee_code=? AND period_key=? AND id<>?",[employee_key($s),$l['date'],$prior['id']])->fetch())fail('يوجد صرف بالتاريخين الأصلي والمصحح؛ لا يدمجان تلقائيًا');v26_insert('history_version',(int)$s['id'],local_time()->format('Y-m-d'),null,['history_id'=>$prior['id'],'before'=>$prior,'after'=>$l,'reason'=>'تصحيح تاريخ الصرف بتوجيه المشرف العام','actor'=>$u['id'],'at'=>utc_now()]);query('UPDATE ep_history SET period_key=?,body_json=? WHERE id=?',[$l['date'],jencode($l+['source'=>'V26']),$prior['id']]);audit('historical_payment_date_corrected','history:'.$prior['id'],['before'=>$body,'after'=>$l]);continue;}
 }
 $old=query("SELECT body_json FROM ep_history WHERE kind='leave_settlement' AND employee_code=? AND period_key=?",[employee_key($s),$l['date']])->fetch();if($old){$v=decode($old['body_json']);if(abs((float)$v['days']-$l['days'])>1e-8||abs((float)$v['amount']-$l['amount'])>0.0005)fail('تعارض صرف إجازة؛ لا يستبدل تلقائيًا');continue;}query('INSERT INTO ep_history(kind,employee_code,period_key,body_json,imported_at,imported_by) VALUES(?,?,?,?,?,?)',['leave_settlement',employee_key($s),$l['date'],jencode($l+['source'=>'V26']),utc_now(),$u['id']]);}
 foreach($doc['banks']as $bank){$s=$map[$bank['serial']];$profile=decode($s['profile_json']);$before=$profile;if($bank['method']==='hold'){$profile['payment_unconfirmed']=false;$profile['payout_on_hold']=true;v26_insert('payout_status',(int)$s['id'],'2026-10-12',null,['held'=>true,'reason'=>'تأكيد المشرف: لا يصرف له حاليًا كاش أو بنك','source'=>'owner_20261012']);}elseif($bank['method']==='unknown'){$profile['payment_unconfirmed']=true;}else{$profile['payment_unconfirmed']=false;foreach(['bank_name','bank_account','iban']as $k)$profile[$k]=$bank[$k];bank_identity_record($s,$profile,$bank['from'],(int)$u['id']);}
 $profile['payroll_visible']=$bank['payroll_visible'];query('UPDATE ep_users SET profile_json=? WHERE id=?',[jencode($profile),$s['id']]);$st=service_state($s,$bank['from']);if($st['period_id']){if(query("SELECT id FROM ep_payroll WHERE user_id=? AND status='approved'",[$s['id']])->fetch())fail('كشف معتمد يمنع تغيير ظهور الموظف بأثر رجعي');v26_insert('service_terms',(int)$s['id'],$bank['from'],null,['payroll'=>$bank['payroll_visible'],'source'=>'V26_bank']);}audit('v26_bank_import','user:'.$s['id'],['before'=>$before,'after'=>$profile]);}
 v26_setting('prepared_v28_history',['hash'=>$p['hash'],'counts'=>$p['counts'],'backup_id'=>$backup['id']]);audit('v26_data_import','batch:'.$p['hash'],['counts'=>$p['counts'],'backup'=>$backup['id']]);db()->commit();unset($GLOBALS['EP_SERVICE_CACHE'],$GLOBALS['V26_ENTITLEMENTS']);return ['counts'=>$p['counts'],'backup_id'=>$backup['id']];
}
